  'tool3-con2' => 'Որոշ գործիքներ ցույց են տալիս սահմանափակումներ անվճար մակարդակի տարբերակի ներքո:',
  'tool3-con3' => 'Դանդաղ ցանցերում ավելի մեծ ֆայլերի վերբեռնումը կարող է ավելի երկար տևել:',
  'comparison-intro' => 'Եկեք համեմատենք դրանց միջև, որպեսզի կարողանաք որոշել, թե որն է ձեր կարիքներին համապատասխան:',
  'table-feature' => 'Առանձնահատկություն',
  'table-adobe' => 'Adobe Acrobat',
  'table-ilovepdf' => 'iLovePDF',
  'table-smallpdf' => 'Smallpdf',
  'table-ease-label' => 'Օգտագործման հեշտություն',
  'table-ease-adobe' => 'Ինտերֆեյսը բարդ է թվում նոր օգտվողների համար',
  'table-ease-ilovepdf' => 'Պարզ քայլերը լավ են սազում սկսնակներին',
  'table-ease-smallpdf' => 'Մաքուր դիզայնը օգնում է արագ հասկանալ',
  'table-cost-label' => 'Արժեքը',
  'table-cost-adobe' => 'Ամբողջական մուտքի համար պահանջվում է վճարովի բաժանորդագրություն',
  'table-cost-ilovepdf' => 'Անվճար տարբերակը ներառում է ամենօրյա օգտագործման սահմանափակումներ',
  'table-cost-smallpdf' => 'Ընդլայնված գործիքների համար անհրաժեշտ է բաժանորդագրություն',
  'table-platform-label' => 'Պլատֆորմի աջակցություն',
  'table-platform-adobe' => 'Աշխատում է աշխատասեղանի և բջջային համակարգերի վրա',
  'table-platform-ilovepdf' => 'Աշխատում է ինտերնետով ցանկացած բրաուզերում',
  'table-platform-smallpdf' => 'Աջակցում է բջջային և աշխատասեղանի բրաուզերներին',
  'table-quality-label' => 'Բացել որակը',
  'table-quality-adobe' => 'Ճշգրիտ պահպանում է դասավորությունը և ձևաչափումը',
  'table-quality-ilovepdf' => 'Լավագույնս աշխատում է պարզ փաստաթղթերով',
  'table-quality-smallpdf' => 'Պահպանում է որակը ավելացված գործիքներով',
  'table-features-label' => 'Լրացուցիչ առանձնահատկություններ',
  'table-features-adobe' => 'Ներառում է խմբագրման և անվտանգության գործիքներ',
  'table-features-ilovepdf' => 'Կենտրոնանում է հիմնական PDF առաջադրանքների վրա',
  'table-features-smallpdf' => 'Առաջարկում է սեղմման և փոխակերպման տարբերակներ',
  'legal-security-heading' => 'Իրավական և անվտանգության նշումներ',
  'legal-security-para1' => 'Տվյալների պաշտպանության օրենքների իմացությունը օգնում է ձեզ խելամտորեն վարվել, երբ բացում եք ձեր պատկանող PDF ֆայլերը: Շատ երկրներ թվային բովանդակությունը պաշտպանում են կանոններով, որոնք արգելում են առանց թույլտվության տեխնիկական կողպեքները հեռացնել:',
  'legal-security-para2-1' => 'Միացյալ Նահանգներում Թվային հազարամյակի հեղինակային իրավունքի մասին օրենքի դրույթը անօրինական է դարձնում մուտքի հսկողության շրջանցումը, որը սահմանափակում է հեղինակային իրավունքով պաշտպանված ստեղծագործության մուտքն առանց սեփականատիրոջ լիազորության: Սույն օրենքը սահմանում է «',
  'legal-security-para2-2' => 'շրջանցել',
  'legal-security-para2-3' => 'որպես պաշտպանված ստեղծագործության շրջանցում կամ վերծանում առանց թույլտվության։',
  'legal-security-para3-1' => 'Չլիազորված մուտքի դեմ օրենքները կարող են կիրառվել նաև այն դեպքում, երբ դուք խախտում եք ձեր չպատկանող ֆայլերի անվտանգությունը: Այն',
  'legal-security-para3-2' => 'Միացյալ Թագավորության Համակարգիչների չարաշահման մասին օրենքը',
  'legal-security-para3-3' => 'Համակարգչային նյութերին առանց թույլտվության մուտք գործելը համարվում է հանցագործություն: Սա ներառում է ձեր չվերահսկվող համակարգի կողպված ֆայլերում պահվող տվյալները: Տույժերը կարող են ներառել տուգանքներ կամ ազատազրկում լուրջ դեպքերի համար:',
  'legal-security-para4' => 'Իրավական աղբյուրները սովորաբար թույլ են տալիս սեփականատերերին կամ թույլատրված օգտատերերին բացել իրենց սեփական ֆայլերը: Թվային իրավունքի աղբյուրներից ստացված խորհուրդն ասում է, որ փաստաթուղթ ունենալը կամ հստակ թույլտվություն ունենալը ապակողպումն օրինական է դարձնում: Եթե ​​դուք չունեք այս թույլտվությունը, ապա պաշտպանության հեռացումը կարող է խախտել ձեր երկրի մտավոր սեփականության կամ համակարգչային մուտքի մասին օրենքները: Միշտ ստուգեք օրենսդրության բնօրինակ տեքստը և անհրաժեշտության դեպքում դիմեք իրավաբանի խորհրդատու:',
  'conclusion-heading' => 'Եզրակացություն',
  'conclusion-para1-1' => 'PDF ֆայլեր',
  'conclusion-para1' => 'հաճախ պահպանում են զգայուն տեղեկատվություն, որը հասանելիության ուժեղ վերահսկման կարիք ունի համօգտագործման ընթացքում: Գաղտնաբառերը պաշտպանում են բովանդակությունը և նվազեցնում չարաշահումը աշխատանքի, կրթության և անձնական հաղորդակցության մեջ: Խնդիրներն առաջանում են, երբ օգտատերերը մոռանում են գաղտնաբառերը կամ ստանում կողպված ֆայլեր ուրիշներից:',
  'conclusion-para2' => 'PDF-ի ապակողպումն օգտագործում է պարզ քայլեր, որոնք սկսվում են պաշտպանված փաստաթղթի վերբեռնումից: Օգտագործողները մուտքագրում են ճիշտ գաղտնաբառը, և գործիքը անվտանգ կերպով հեռացնում է գաղտնագրումը: Լավ գործիքները պահպանում են դասավորությունը և թույլ են տալիս դիտել, խմբագրել և կիսվել առանց սահմանափակումների:',
  'conclusion-para3' => 'Adobe Acrobat-ը, iLovePDF-ը և Smallpdf-ն առաջարկում են PDF ապակողպման հուսալի լուծումներ: Յուրաքանչյուր գործիք տրամադրում է տարբեր հատկանիշներ, ծախսեր և օգտագործման հեշտ մակարդակներ: Իրավական կանոնները թույլ են տալիս ապակողպումը միայն սեփականության իրավունքով կամ հստակ թույլտվությամբ:',
  'faqs-heading' => 'ՀՏՀ-ներ',
  'faq1-question' => 'Արդյո՞ք PDF ֆայլերի ապակողպումը օրինական է:',
  'faq1-answer' => 'PDF ֆայլերի ապակողպումը օրինական է միայն այն դեպքում, եթե դուք ունեք փաստաթուղթը կամ ունեք հստակ թույլտվություն: Օրենքները կանխում են չարտոնված մուտքը, և դրանք խախտելը կարող է հանգեցնել տուգանքների կամ իրավական գործողությունների: Միշտ հաստատեք սեփականությունը՝ նախքան որևէ ֆայլից գաղտնաբառի պաշտպանությունը հեռացնելը:',
  'faq2-question' => 'Կարո՞ղ եմ անվճար բացել PDF ֆայլերը:',
  'faq2-answer' => 'Շատ առցանց գործիքներ թույլ են տալիս օգտվողներին բացել PDF ֆայլերը առանց վճարելու, թեև հաճախ սահմանափակումներ են կիրառվում: Անվճար ծառայությունները սովորաբար սահմանափակում են ֆայլի չափը, ամենօրյա օգտագործումը կամ առաջադեմ գործառույթները: Օգտագործողները կարող են կատարել հիմնական ապակողպման առաջադրանքները առանց բաժանորդագրությունների՝ օգտագործելով վստահելի վեբ հարթակներ:',
  'faq3-question' => 'Արդյո՞ք ապակողպումը վերացնում է գաղտնագրումը:',
  'faq3-answer' => 'PDF-ի ապակողպումը վերացնում է գաղտնագրման շերտը, որն արգելափակում է մուտքը դեպի բովանդակություն: Սա թույլ է տալիս դիտել, խմբագրել և փոխանակել ֆայլերը առանց սահմանափակումների: Ուժեղ գործիքները պահպանում են բնօրինակ դասավորությունը և պաշտպանում տեքստը, պատկերները և հղումները փաստաթղթի ներսում:',
  'faq4-question' => 'Արդյո՞ք անհրաժեշտ է գաղտնաբառ PDF-ը բացելու համար:',
  'faq4-answer' => 'PDF ապակողպման գործիքներից շատերը պահանջում են ճիշտ գաղտնաբառ նախքան մուտքի թույլտվությունը: Սխալ գաղտնաբառ մուտքագրելը թույլ չի տալիս ամբողջությամբ ապակողպել: Գաղտնաբառը հաստատում է սեփականության իրավունքը և ապահովում է միայն լիազորված օգտվողները կարող են հեռացնել սահմանափակումները ֆայլից:',
  'faq5-question' => 'Արդյո՞ք ֆայլերը պահվում են առցանց:',
  'faq5-answer' => 'Շատ PDF ապակողպման ծառայություններ ապակողպման ընթացքում ֆայլերը ժամանակավորապես մշակում են անվտանգ սերվերների վրա: Վստահելի հարթակները կարճ ժամանակահատվածից հետո ավտոմատ կերպով ջնջում են ֆայլերը: Օգտագործողները պետք է խուսափեն ծառայությունների վրա զգայուն փաստաթղթեր վերբեռնելուց՝ առանց գաղտնիության և անվտանգության հստակ քաղաքականության:',
);
